export interface WritingWorkshopPromptPack {
  system: string;
  contextRule: string;
  kindLabels: Record<string, string>;
  fallback: WritingWorkshopFallbackCopy;
}

const jsonSchema = {
  title: '"title": "academic title",',
  abstract: '"abstract": "5-8 lines summarizing the section thesis",',
  outline: '    {"id":"s1","title":"...","purpose":"...","keyClaims":["..."],"sources":["[Surname, I. (year)](nodus://idea/g-0001)"]}',
  draft: '  "draftMarkdown": "Markdown draft with H2/H3, paragraphs, and nodus:// citations",',
  matrix: '    {"claim":"...","role":"support|contrast|gap|method|definition|context","sourceLabel":"Surname, I. (year)","citation":"nodus://idea/g-0001","evidence":"anchored quotation or summary","notes":"use in the argument"}',
  bibliography: '  "bibliography": ["Surname, I. (year). Title."],',
};

const citationFormats = [
  '- Ideas: [Surname, I. (year)](nodus://idea/<global_id>)',
  '- Works: [Surname, I. (year)](nodus://work/<nodus_id>)',
  '- Gaps: [gap](nodus://gap/<gap_id>)',
  '- Contradictions: [contradiction](nodus://contradiction/<edge_id>)',
  '- Full-text passages: [Surname, year, p. N](nodus://passage/<passage_id>)',
];

function systemPack(lines: string[]): string {
  const first = lines[0] ?? '';
  const language = first.startsWith('You are') ? 'en' : first.startsWith('Tu es') ? 'fr' : first.startsWith('Du bist') ? 'de' : first.startsWith('És') ? 'pt' : first.startsWith('Você') ? 'pt-BR' : first.startsWith('Sei') ? 'it' : first.startsWith('Nodus Yazım') ? 'tr' : first.startsWith('你是 Nodus 写作') ? 'zh-Hans' : first.startsWith('你是 Nodus 寫作') ? 'zh-Hant' : first.startsWith('Bạn là') ? 'vi' : first.startsWith('あなたは') ? 'ja' : first.startsWith('Вы —') ? 'ru' : first.startsWith('Ви —') ? 'uk' : first.startsWith('당신은') ? 'ko' : 'es';
  const outputInstruction = {
    es: 'Devuelve EXCLUSIVAMENTE JSON válido con esta forma:', en: 'Return EXCLUSIVELY valid JSON with this shape:', fr: 'Renvoie EXCLUSIVEMENT un JSON valide de cette forme :', de: 'Gib AUSSCHLIESSLICH gültiges JSON in dieser Form zurück:', pt: 'Devolve EXCLUSIVAMENTE JSON válido com esta forma:', 'pt-BR': 'Retorne EXCLUSIVAMENTE JSON válido neste formato:', it: 'Restituisci ESCLUSIVAMENTE JSON valido in questa forma:', tr: 'YALNIZCA bu biçimde geçerli JSON döndür:', 'zh-Hans': '仅返回如下形式的有效 JSON：', 'zh-Hant': '僅返回如下形式的有效 JSON：', vi: 'Chỉ trả về JSON hợp lệ đúng theo dạng sau:', ja: '次の形式の有効な JSON のみを返してください：', ru: 'Верните ИСКЛЮЧИТЕЛЬНО действительный JSON следующей формы:', uk: 'Поверніть ВИКЛЮЧНО дійсний JSON такої форми:', ko: '다음 형식의 유효한 JSON만 반환하십시오:',
  }[language];
  const authorExample = ({ es: 'Apellido', en: 'Surname', fr: 'Nom', de: 'Nachname', pt: 'Apelido', 'pt-BR': 'Sobrenome', it: 'Cognome', tr: 'Soyadı', 'zh-Hans': '姓氏', 'zh-Hant': '姓氏', vi: 'Họ', ja: '姓', ru: 'Фамилия', uk: 'Прізвище', ko: '성' } as Record<string, string>)[language];
  const yearExample = ({ es: 'año', en: 'year', fr: 'année', de: 'Jahr', pt: 'ano', 'pt-BR': 'ano', it: 'anno', tr: 'yıl', 'zh-Hans': '年份', 'zh-Hant': '年份', vi: 'năm', ja: '年', ru: 'год', uk: 'рік', ko: '연도' } as Record<string, string>)[language];
  const outlineExample = jsonSchema.outline.replaceAll('Surname', authorExample).replaceAll('year', yearExample);
  const schemaLabels = {
    es: ['título académico breve', '5-8 líneas que resumen la tesis del apartado', 'borrador en Markdown con H2/H3, párrafos y citas nodus://', 'cita o resumen anclado', 'uso en el argumento', 'Título'],
    en: ['academic title', '5-8 lines summarizing the section thesis', 'Markdown draft with H2/H3, paragraphs, and nodus:// citations', 'anchored quotation or summary', 'use in the argument', 'Title'],
    fr: ['titre universitaire bref', '5 à 8 lignes résumant la thèse de la section', 'brouillon Markdown avec H2/H3, paragraphes et citations nodus://', 'citation ou résumé ancré', 'usage dans l’argumentation', 'Titre'],
    de: ['kurzer wissenschaftlicher Titel', '5–8 Zeilen zur Zusammenfassung der Abschnittsthese', 'Markdown-Entwurf mit H2/H3, Absätzen und nodus://-Zitaten', 'verankertes Zitat oder eine Zusammenfassung', 'Verwendung im Argument', 'Titel'],
    pt: ['título académico breve', '5-8 linhas que resumem a tese da secção', 'rascunho em Markdown com H2/H3, parágrafos e citações nodus://', 'citação ou resumo ancorado', 'uso no argumento', 'Título'],
    'pt-BR': ['título acadêmico breve', '5-8 linhas que resumem a tese da seção', 'rascunho em Markdown com H2/H3, parágrafos e citações nodus://', 'citação ou resumo ancorado', 'uso no argumento', 'Título'],
    it: ['breve titolo accademico', '5-8 righe che riassumono la tesi della sezione', 'bozza in Markdown con H2/H3, paragrafi e citazioni nodus://', 'citazione o riassunto ancorato', 'uso nell’argomentazione', 'Titolo'],
    tr: ['kısa akademik başlık', 'bölüm tezini özetleyen 5-8 satır', 'H2/H3, paragraflar ve nodus:// alıntıları içeren Markdown taslağı', 'temellendirilmiş alıntı veya özet', 'argümandaki kullanım', 'Başlık'],
    'zh-Hans': ['简短的学术标题', '5-8 行，概述本节的论点', '包含 H2/H3、段落和 nodus:// 引用的 Markdown 草稿', '有出处的引文或摘要', '在论证中的用途', '标题'],
    'zh-Hant': ['簡短的學術標題', '5-8 行，概述本節的論點', '包含 H2/H3、段落和 nodus:// 引用的 Markdown 草稿', '有出處的引文或摘要', '在論證中的用途', '標題'],
    vi: ['tiêu đề học thuật ngắn gọn', '5-8 dòng tóm tắt luận điểm của mục này', 'bản thảo Markdown có H2/H3, các đoạn văn và trích dẫn nodus://', 'trích dẫn hoặc tóm tắt có neo', 'cách dùng trong lập luận', 'Tiêu đề'],
    ja: ['簡潔な学術的タイトル', 'この節の主張を要約する5-8行', 'H2/H3、段落、nodus:// 引用を含む Markdown ドラフト', '根拠づけられた引用または要約', '論証での用途', 'タイトル'],
    ru: ['краткое академическое название', '5–8 строк, резюмирующих тезис раздела', 'черновик в Markdown с H2/H3, абзацами и ссылками nodus://', 'привязанная цитата или резюме', 'использование в аргументации', 'Название'],
    uk: ['коротка академічна назва', '5–8 рядків, що узагальнюють тезу розділу', 'чернетка у Markdown з H2/H3, абзацами та посиланнями nodus://', 'прив’язана цитата або резюме', 'використання в аргументації', 'Назва'],
    ko: ['간결한 학술 제목', '이 절의 논지를 요약하는 5-8줄', 'H2/H3, 단락, nodus:// 인용을 포함한 Markdown 초안', '근거가 붙은 인용 또는 요약', '논증에서의 용도', '제목'],
  }[language];
  return [
    ...lines,
    '',
    outputInstruction,
    '{',
    `  "title": "${schemaLabels[0]}",`,
    `  "abstract": "${schemaLabels[1]}",`,
    '  "outline": [',
    outlineExample,
    '  ],',
    `  "draftMarkdown": "${schemaLabels[2]}",`,
    '  "matrix": [',
    `    {"claim":"...","role":"support|contrast|gap|method|definition|context","sourceLabel":"${authorExample}, I. (${yearExample})","citation":"nodus://idea/g-0001","evidence":"${schemaLabels[3]}","notes":"${schemaLabels[4]}"}`,
    '  ],',
    `  "bibliography": ["${authorExample}, I. (${yearExample}). ${schemaLabels[5]}."],`,
    '  "nextSteps": ["..."],',
    '  "limitations": ["..."]',
    '}',
  ].join('\n');
}

